package com.bte.controller;
import com.bte.repository.*;import com.bte.entity.*;import com.bte.enums.*;import com.bte.service.*;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.*;import org.springframework.http.*;import java.util.*;import java.math.BigDecimal;
@RestController @RequiredArgsConstructor @RequestMapping("/api/v1/admin/operations")
public class AdminOperationsController {
 private final TournamentRepository tournaments;private final LedgerTransactionRepository ledger;private final ScoreAuditRepository audits;
 public record Organizer(Long userId,String name,long tournaments,long completed,long active,BigDecimal escrowVolume,BigDecimal commission){}
 public record Overview(long activeRooms,long activeOrganizers,List<Organizer> organizers){}
 @GetMapping @Transactional(readOnly=true)public Overview overview(){var rooms=tournaments.findAll().stream().filter(t->!t.isArchived()).toList();var ids=rooms.stream().map(Tournament::getId).toList();var volumes=new HashMap<Long,BigDecimal>();var commissions=new HashMap<Long,BigDecimal>();if(!ids.isEmpty())for(var row:ledger.totals(ids)){Long id=(Long)row[0];var type=(LedgerTransactionType)row[1];var amount=(BigDecimal)row[2];if(type==LedgerTransactionType.ESCROW_HOLD || type==LedgerTransactionType.ESCROW_LOCK)volumes.merge(id,amount,BigDecimal::add);if(type==LedgerTransactionType.ORGANIZER_COMMISSION || type==LedgerTransactionType.LEADER_COMMISSION)commissions.merge(id,amount,BigDecimal::add);}var groups=new LinkedHashMap<Long,List<Tournament>>();rooms.forEach(t->groups.computeIfAbsent(t.getLeader().getId(),k->new ArrayList<>()).add(t));var output=new ArrayList<Organizer>();for(var group:groups.entrySet()){var items=group.getValue();output.add(new Organizer(group.getKey(),items.getFirst().getLeader().getName(),items.size(),items.stream().filter(t->t.getStatus()==TournamentStatus.COMPLETED).count(),items.stream().filter(this::active).count(),items.stream().map(t->volumes.getOrDefault(t.getId(),BigDecimal.ZERO)).reduce(BigDecimal.ZERO,BigDecimal::add),items.stream().map(t->commissions.getOrDefault(t.getId(),BigDecimal.ZERO)).reduce(BigDecimal.ZERO,BigDecimal::add)));}return new Overview(rooms.stream().filter(this::active).count(),output.stream().filter(o->o.active()>0 && groups.get(o.userId()).getFirst().getLeader().getRole()==Role.ROLE_ORGANIZER && !groups.get(o.userId()).getFirst().getLeader().isBlocked()).count(),output);}
 private boolean active(Tournament t){return t.getStatus()==TournamentStatus.UPCOMING || t.getStatus()==TournamentStatus.LIVE || t.getStatus()==TournamentStatus.UNDER_REVIEW;}
 @GetMapping("/tournaments/{id}/ledger")public Page<LedgerTransaction> ledger(@PathVariable Long id,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){if(page<0 || size<1 || size>200)throw new com.bte.exception.BadRequestException("Invalid pagination");return ledger.findByTournamentIdOrderByIdAsc(id,PageRequest.of(page,size));}
 @GetMapping("/match-results/{id}/audit")public List<ScoreAudit> audit(@PathVariable Long id){return audits.findByMatchResultIdOrderByRevisionAsc(id);}
 @GetMapping(value="/tournaments/{id}/ledger.csv",produces="text/csv")public ResponseEntity<org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody> csv(@PathVariable Long id){if(!tournaments.existsById(id))throw new com.bte.exception.ResourceNotFoundException("Tournament not found");Long upper=ledger.maxId(id);return ResponseEntity.ok().contentType(new MediaType("text","csv",java.nio.charset.StandardCharsets.UTF_8)).header("Content-Disposition","attachment; filename=\"battletrust-tournament-"+id+"-ledger.csv\"").header("Cache-Control","no-store").body(output->{var writer=new java.io.OutputStreamWriter(output,java.nio.charset.StandardCharsets.UTF_8);writer.write(LedgerCsv.line("id","tournament_id","type","sender_id","receiver_id","amount_pkr","reference","created_at_utc"));long after=0;while(true){var batch=ledger.findByTournamentIdAndIdGreaterThanAndIdLessThanEqualOrderByIdAsc(id,after,upper,PageRequest.of(0,500));if(batch.isEmpty())break;for(var row:batch){writer.write(LedgerCsv.line(row.getId(),row.getTournamentId(),row.getTransactionType(),row.getSenderId(),row.getReceiverId(),row.getAmount(),row.getReferenceId(),row.getCreatedAt()));after=row.getId();}writer.flush();}writer.flush();});}
}
